				return err
			}
			return runCoreMutation(cmd, func(ctx context.Context, c *coreapi.Client) (string, any, error) {
				repoID, err := resolveRepoRef(ctx, c, args[0], project)
				if err != nil {
					return "", nil, err
				}
				provider, providerUserID, err := resolveGranteeProvider(ctx, c, args[1])
				if err != nil {
