					Role:           coreapi.GrantRepoAccessInputBodyRole(role),
				}
				out, err := c.GrantRepoAccess(ctx, body, coreapi.GrantRepoAccessParams{RepoId: repoID})
				if err != nil {
					return "", nil, err
				}
